\copy (SELECT t.kod, COALESCE(NULLIF(s.il,''), t.sehir, '') AS il, COALESCE(s.ilce,'') AS ilce, COALESCE(s.segment,'') AS segment, COALESCE(array_to_string(s.sektorler,'|'),'') AS sektorler FROM (SELECT DISTINCT ON (m.musteri_kodu) m.musteri_kodu AS kod, m.sehir FROM master_musteri m JOIN (SELECT DISTINCT ON (muhatap_kodu) muhatap_kodu, grup FROM bi_musteri_risk WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND musteri_mi ORDER BY muhatap_kodu, export_date DESC NULLS LAST) r ON r.muhatap_kodu=m.musteri_kodu WHERE m.tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND r.grup IN ('FILO TICARI','TOPTAN','KURUM','IMALATCI','IHRACAT','GRUP MUSTERILERI') ORDER BY m.musteri_kodu) t LEFT JOIN (SELECT DISTINCT ON (musteri_kodu) musteri_kodu AS kod, il, ilce, segment, sektorler FROM saha_musteri WHERE tenant_id='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa' AND musteri_kodu IS NOT NULL ORDER BY musteri_kodu, aktif DESC, updated_at DESC NULLS LAST) s ON s.kod=t.kod ORDER BY t.kod) TO STDOUT WITH CSV HEADER
